    #[tokio::test]
    async fn session_database_failure_is_an_error_for_authenticated_fields() {
        let (schema, pool) = setup_full(100).await;
        pool.close().await;
        for query in ["{ session { token } }", "{ library { id } }"] {
            let response = exec(&schema, query, Some("bobtok"), "1.1.1.1").await;
            assert!(
                !response.errors.is_empty(),
                "database outage appeared anonymous: {query}"
            );
            assert_eq!(response.errors[0].message, "Server busy; retry soon");
            assert_eq!(
                response.errors[0].extensions.as_ref().unwrap().get("code"),
                Some(&async_graphql::Value::String("SERVICE_UNAVAILABLE".into()))
            );
        }
        let anonymous = exec(&schema, "{ session { token } }", None, "1.1.1.1").await;
        assert!(anonymous.errors.is_empty());
        assert_eq!(
            anonymous.data.into_json().unwrap()["session"],
            serde_json::Value::Null
        );
    }

    #[tokio::test]
    async fn library_identity_retries_a_fresh_transaction_after_an_external_writer() {
        let (_, pool) = setup_full(100).await;
        sqlx::query("INSERT INTO user_library (user_id, series_id, created_at) VALUES ('bob-id', 's1', 't')")
            .execute(&pool).await.unwrap();
        let external = sqlx::sqlite::SqlitePoolOptions::new()
            .max_connections(1)
            .connect_with(
                (*pool.connect_options())
                    .clone()
                    .pragma("query_only", "OFF"),
            )
            .await
            .unwrap();
        let writer = external.begin_with("BEGIN IMMEDIATE").await.unwrap();
        let task_pool = pool.clone();
        let task = tokio::spawn(async move {
            consolidate_library_identity(&task_pool, "bob-id", "w_s1").await
        });
        tokio::time::sleep(Duration::from_millis(350)).await;
        writer.commit().await.unwrap();
        assert_eq!(task.await.unwrap().unwrap(), "w_s1");
        let identities: Vec<String> =
            sqlx::query_scalar("SELECT series_id FROM user_library WHERE user_id = 'bob-id'")
                .fetch_all(&pool)
                .await
                .unwrap();
        assert_eq!(identities, ["w_s1"]);
        external.close().await;
        pool.close().await;
    }

    #[tokio::test]
    async fn concurrent_partial_chapter_overrides_preserve_both_fields() {
        let (schema, pool) = setup_full(100).await;
        let hide = exec(
            &schema,
            r#"mutation { setChapterOverride(input: {workId: "w_s1", chapterKey: "1", hidden: true}) }"#,
            Some("admintok"),
            "1.1.1.1",
        );
        let rename = exec(
            &schema,
            r#"mutation { setChapterOverride(input: {workId: "w_s1", chapterKey: "1", title: "Renamed"}) }"#,
            Some("admintok"),
            "1.1.1.1",
        );
        let (hide, rename) = tokio::join!(hide, rename);
        assert!(hide.errors.is_empty(), "{:?}", hide.errors);
        assert!(rename.errors.is_empty(), "{:?}", rename.errors);
        let row: (i64, Option<String>) = sqlx::query_as(
            "SELECT hidden, title_override FROM chapter_override WHERE work_id = 'w_s1' AND chapter_key = '1'",
        ).fetch_one(&pool).await.unwrap();
        assert_eq!(row, (1, Some("Renamed".into())));
        pool.close().await;
    }

    async fn setup_with_state(max: u32) -> (ApiSchema, Database, std::sync::Arc<AppState>) {
        setup_with_engine(max, "http://127.0.0.1:1").await
    }

    /// [`setup_with_state`] with the Suwayomi engine at `engine_url` — for the resolvers
    /// that ask the engine something (the default address answers nothing).
    async fn setup_with_engine(
        max: u32,
        engine_url: &str,
    ) -> (ApiSchema, Database, std::sync::Arc<AppState>) {
        let pool = TestPoolOptions::new()
            .max_connections(1)
            .connect("sqlite::memory:")
            .await
            .unwrap();
        sqlx::migrate!("./migrations")
            .run(pool.write())
            .await
            .unwrap();
        seed_user(&pool, "admin-id", "admin", 1, 0).await;
        seed_user(&pool, "bob-id", "bob", 0, 0).await;
        seed_user(&pool, "banned-id", "carol", 0, 1).await;
        // Sessions store sha256(token); clients still present the raw token
        // ("admintok"/"bobtok") in the Authorization header, which `user_for_token`
        // re-hashes before lookup — so seed the hashed value here.
        for (tok, uid) in [("admintok", "admin-id"), ("bobtok", "bob-id")] {
            sqlx::query(
                "INSERT INTO sessions (token, user_id, created_at, expires_at) \
                 VALUES (?, ?, '2020-01-01T00:00:00Z', '2999-01-01T00:00:00Z')",
            )
            .bind(auth::hash_token(tok))
            .bind(uid)
            .execute(&pool)
            .await
            .unwrap();
        }
        // An already-expired session — its token must not resolve (A1).
        sqlx::query(
            "INSERT INTO sessions (token, user_id, created_at, expires_at) \
             VALUES (?, 'bob-id', '2020-01-01T00:00:00Z', '2020-02-01T00:00:00Z')",
        )
        .bind(auth::hash_token("expiredtok"))
        .execute(&pool)
        .await
        .unwrap();
        // Comment/review targets used across the social tests. `postComment`/`postReview`
        // now REJECT ids that resolve to nothing (they write into FK-less TEXT columns),
        // so the threads these tests open must hang off real rows.
        seed_target_series(&pool, "s1").await;
        seed_target_series(&pool, "s2").await;
        sqlx::query(
            "INSERT INTO suwayomi_series (id, title, status, source_id, chapter_count, updated_at) \
             VALUES (42, 'Fixture 42', 'ONGOING', 'src', 0, '2020-01-01T00:00:00Z')",
        )
        .execute(&pool)
        .await
        .unwrap();
        let state = std::sync::Arc::new(AppState {
            pool: pool.clone(),
            cover_pool: pool.clone(),
            suwayomi: crate::suwayomi::SuwayomiClient::new(engine_url.into(), None, None),
            mangadex: std::sync::Arc::new(crate::mangadex::MangaDexClient::new(
                "test-ua", 5.0, 40.0,
            )),
            admin_users: vec![],
            scan_health: Mutex::new(ScanHealth::default()),
            auth_limiter: RateLimiter::new(max, 60),
            comment_limiter: comment_limiter(),
            password_work: std::sync::Arc::new(tokio::sync::Semaphore::new(4)),
            federated_limiter: RateLimiter::new(100, 60),
            session_ttl_secs: 30 * 24 * 60 * 60,
            series_inflight: KeyedLocks::default(),
            chapters_inflight: KeyedLocks::default(),
            cover_crawl_running: std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false)),
            catalogue_cover_phash: false,
            ext_icons_dir: std::path::PathBuf::new(),
            setup_code: crate::instance::SetupCode::default(),
        });
        (build_schema(state.clone(), false), pool, state)
    }

    /// `chapterOrigin` tells a reader app where a chapter lives so it can fetch the pages
    /// itself. That is as good as serving them, so it carries the same NSFW gate as
    /// `pages`; and it must hand out the source's keys and the extension, never our ids.
    #[tokio::test]
    async fn chapter_origin_is_nsfw_gated_and_carries_the_extension() {
        let engine = crate::suwayomi::testsrv::spawn_status(
            200,
            "application/json",
            br##"{"data":{"chapters":{"nodes":[{"url":"#/viewer/1030381",
                "realUrl":"https://mangaplus.shueisha.co.jp/viewer/1030381","mangaId":77,
                "manga":{"url":"#/titles/100020",
                         "realUrl":"https://mangaplus.shueisha.co.jp/titles/100020",
                         "title":"One Piece","sourceId":"src-9"}}]}}}"##
                .to_vec(),
            Duration::ZERO,
        )
        .await;
        let (s, pool, _) = setup_with_engine(100, &engine.base_url).await;
        sqlx::query(
            "INSERT INTO source_extension (source_id, pkg_name, repo_url, is_nsfw, updated_at) \
             VALUES ('src-9', 'org.example.ext', 'https://example/index.pb', 0, '2026-01-01T00:00:00Z')",
        )
        .execute(&pool)
        .await
        .unwrap();
        const Q: &str = r#"{ chapterOrigin(chapterId: "6") {
            sourceId mangaUrl mangaTitle chapterUrl chapterWebUrl mangaWebUrl
            extension { pkgName repoUrl } } }"#;

        // Not linked to an NSFW work: anyone gets the coordinates.
        let r = exec(&s, Q, None, "1.1.1.1").await;
        assert!(r.errors.is_empty(), "unexpected: {:?}", r.errors);
        let j = data_json(&r);
        for want in [
            r##""sourceId":"src-9""##,
            r##""mangaUrl":"#/titles/100020""##,
            r##""mangaTitle":"One Piece""##,
            r##""chapterUrl":"#/viewer/1030381""##,
            // The pages a person can open — what "Read on source" links to.
            r##""chapterWebUrl":"https://mangaplus.shueisha.co.jp/viewer/1030381""##,
            r##""mangaWebUrl":"https://mangaplus.shueisha.co.jp/titles/100020""##,
            r##""pkgName":"org.example.ext""##,
            r##""repoUrl":"https://example/index.pb""##,
        ] {
            assert!(j.contains(want), "missing {want} in {j}");
        }
        assert!(
            !j.contains("77"),
            "our engine's manga id must not leak: {j}"
        );

        // The owning manga (engine id 77) belongs to an NSFW work.
        sqlx::query(
            "INSERT INTO work (id, primary_title, is_nsfw, created_at, updated_at) \
             VALUES ('w_adult', 'Adult', 1, '2026-01-01T00:00:00Z', '2026-01-01T00:00:00Z')",
        )
        .execute(&pool)
        .await
        .unwrap();
        sqlx::query(
            "INSERT INTO source_series (id, work_id, source_type, source_id, source_key, created_at) \
             VALUES ('ss_adult', 'w_adult', 'suwayomi', 'src-9', '77', '2026-01-01T00:00:00Z')",
        )
        .execute(&pool)
        .await
        .unwrap();
        // Signed out, and signed in without the preference: refused, nothing leaks.
        for token in [None, Some("bobtok")] {
            let r = exec(&s, Q, token, "1.1.1.1").await;
            assert!(!r.errors.is_empty(), "NSFW origin served to {token:?}");
            assert!(
                !data_json(&r).contains("viewer"),
                "leaked: {}",
                data_json(&r)
            );
        }
        // Opted in: served.
        sqlx::query("UPDATE users SET show_nsfw = 1 WHERE id = 'bob-id'")
            .execute(&pool)
            .await
            .unwrap();
        let r = exec(&s, Q, Some("bobtok"), "1.1.1.1").await;
        assert!(r.errors.is_empty(), "unexpected: {:?}", r.errors);
        assert!(data_json(&r).contains("#/viewer/1030381"));
    }

    /// One reply that answers every engine document the ingest and extension paths
    /// send (the fake engine serves a single fixed body, and each caller reads only its
    /// own key out of `data`): the manga detail, the library update, the installed
    /// extensions with their sources, one source's own flags, an extension patch, and a
    /// chapter's origin. One extension, `pkg.adult`, providing source `1534`.
    fn engine_reply(extension_is_nsfw: bool) -> Vec<u8> {
        serde_json::json!({ "data": {
            "fetchMangaAndChapters": {
                "manga": {
                    "id": 501, "title": "Quiet Office Days", "url": "/series/quiet",
                    "thumbnailUrl": null, "author": null, "artist": null,
                    "description": null, "genre": ["Action"], "status": "ONGOING",
                    "inLibrary": false, "inLibraryAt": null, "lastFetchedAt": null,
                    "sourceId": "1534", "source": { "lang": "en" },
                    "chapters": { "totalCount": 0 }
                },
                "chapters": []
            },
            "updateManga": { "manga": { "id": 501 } },
            "extensions": { "nodes": [{
                "pkgName": "pkg.adult", "repo": "https://example.org/index.pb",
                "apkName": "adult-v7.apk", "versionCode": 7, "lang": "en",
                "isNsfw": extension_is_nsfw, "source": { "nodes": [{ "id": "1534" }] }
            }] },
            "source": { "displayName": "Adult", "isNsfw": extension_is_nsfw, "lang": "en" },
            "updateExtension": { "extension": {
                "pkgName": "pkg.adult", "name": "Adult", "lang": "en",
                "versionName": "1.4.7", "isInstalled": true, "hasUpdate": false,
                "isNsfw": extension_is_nsfw, "iconUrl": null,
                "repo": "https://example.org/index.pb"
            } },
            "chapters": { "nodes": [{
                "url": "/ch/1", "mangaId": 501,
                "manga": { "url": "/series/quiet", "title": "Quiet Office Days",
                           "sourceId": "1534" }
            }] }
        } })
        .to_string()
        .into_bytes()
    }

    async fn recorded_source_nsfw(pool: &Database, source_id: &str) -> Option<i64> {
        sqlx::query_scalar("SELECT is_nsfw FROM source_extension WHERE source_id = ?")
            .bind(source_id)
            .fetch_optional(pool)
            .await
            .unwrap()
    }

    /// The leak this guards: on a fresh server (or right after an extension install)
    /// `source_extension` has no row for the source, and ingest read "no row" as "not an
    /// adult source". Every series of an adult extension whose own genres are not adult
    /// was stored safe and served to signed-out visitors. Driven through the real
    /// `bulkAddSourceSeries` mutation against a fake engine that flags the source NSFW.
    #[tokio::test]
    async fn bulk_add_from_an_unrecorded_adult_source_stores_the_work_adult() {
        let engine = crate::suwayomi::testsrv::spawn_status(
            200,
            "application/json",
            engine_reply(true),
            Duration::ZERO,
        )
        .await;
        let (s, pool, _) = setup_with_engine(100, &engine.base_url).await;
        assert_eq!(
            recorded_source_nsfw(&pool, "1534").await,
            None,
            "precondition: the source is not recorded"
        );

        let r = exec(
            &s,
            r#"mutation { bulkAddSourceSeries(suwayomiMangaIds: ["501"]) {
                succeeded failed entries { error } } }"#,
            Some("admintok"),
            "1.1.1.1",
        )
        .await;
        assert!(r.errors.is_empty(), "{:?}", r.errors);
        assert!(
            data_json(&r).contains(r#""succeeded":1"#),
            "{}",
            data_json(&r)
        );

        let work_id: String = sqlx::query_scalar(
            "SELECT work_id FROM source_series \
             WHERE source_type = 'suwayomi' AND source_id = '1534' AND source_key = '501'",
        )
        .fetch_one(&pool)
        .await
        .unwrap();
        let (work_nsfw, series_nsfw): (i64, i64) = sqlx::query_as(
            "SELECT w.is_nsfw, ss.is_nsfw FROM work w \
             JOIN source_series ss ON ss.work_id = w.id WHERE w.id = ?",
        )
        .bind(&work_id)
        .fetch_one(&pool)
        .await
        .unwrap();
        assert_eq!(
            (work_nsfw, series_nsfw),
            (1, 1),
            "an adult source's series is adult"
        );
        // The first miss recorded the source, so the next series is a plain row read.
        assert_eq!(recorded_source_nsfw(&pool, "1534").await, Some(1));

        // A signed-out visitor, and a signed-in one who has not opted in, get nothing.
        let q = format!(r#"{{ aggregatedChapters(workId: "{work_id}") {{ number }} }}"#);
        for token in [None, Some("bobtok")] {
            let r = exec(&s, &q, token, "1.1.1.1").await;
            assert_eq!(
                r.errors.first().map(|e| e.message.as_str()),
                Some("No such work"),
                "adult work served to {token:?}"
            );
        }
        sqlx::query("UPDATE users SET show_nsfw = 1 WHERE id = 'bob-id'")
            .execute(&pool)
            .await
            .unwrap();
        let r = exec(&s, &q, Some("bobtok"), "1.1.1.1").await;
        assert!(r.errors.is_empty(), "opted in: {:?}", r.errors);
    }

    /// The other half of the same decision: an unrecorded source the engine calls safe
    /// is ingested as safe (unknown is resolved, not assumed adult), and a source nobody
    /// can classify is refused rather than added as safe.
    #[tokio::test]
    async fn an_unrecorded_source_is_asked_about_and_an_unanswerable_one_is_refused() {
        let engine = crate::suwayomi::testsrv::spawn_status(
            200,
            "application/json",
            engine_reply(false),
            Duration::ZERO,
        )
        .await;
        let (_, pool, st) = setup_with_engine(100, &engine.base_url).await;
        assert_eq!(
            resolve_source_nsfw(&st, "1534").await.unwrap(),
            SourceNsfw {
                adult: false,
                pinned: false
            }
        );
        assert_eq!(recorded_source_nsfw(&pool, "1534").await, Some(0));
        // A source no installed extension provides (the Local source) is answered by
        // the source itself, and writes no row.
        assert_eq!(
            resolve_source_nsfw(&st, "0").await.unwrap(),
            SourceNsfw::default()
        );
        assert_eq!(recorded_source_nsfw(&pool, "0").await, None);

        // No row and no engine (the default test engine address answers nothing).
        let (_, pool, st) = setup_with_state(100).await;
        let m = suwayomi_manga(77, "Unclassifiable", &["Action"], "ghost");
        let err = add_source_series_checked(&st, &m, None, false)
            .await
            .err()
            .expect("an unclassifiable source must not be added as safe");
        assert!(err.to_string().contains("adult source"), "{err}");
        let works: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM source_series WHERE source_type = 'suwayomi' AND source_id = 'ghost'",
        )
        .fetch_one(&pool)
        .await
        .unwrap();
        assert_eq!(works, 0, "nothing was linked");
        // With the row there, the engine is not needed at all.
        sqlx::query(
            "INSERT INTO source_extension (source_id, pkg_name, repo_url, is_nsfw, updated_at) \
             VALUES ('ghost', 'pkg', 'repo', 1, '2026-01-01T00:00:00Z')",
        )
        .execute(&pool)
        .await
        .unwrap();
        let r = add_source_series_checked(&st, &m, None, false)
            .await
            .unwrap();
        let nsfw: i64 = sqlx::query_scalar("SELECT is_nsfw FROM work WHERE id = ?")
            .bind(&r.work_id)
            .fetch_one(&pool)
            .await
            .unwrap();
        assert_eq!(nsfw, 1);
    }

    /// `installExtension` / `updateExtension` record the extension's sources at once, so
    /// `chapterOrigin` can hand a reader app the extension to install without waiting for
    /// the scheduled record pass. A record step that fails does not fail the install.
    #[tokio::test]
    async fn install_and_update_extension_record_sources_for_chapter_origin() {
        let engine = crate::suwayomi::testsrv::spawn_status(
            200,
            "application/json",
            engine_reply(true),
            Duration::ZERO,
        )
        .await;
        let (s, pool, _) = setup_with_engine(100, &engine.base_url).await;
        // The extension is NSFW; the admin has to have opted in to install it.
        sqlx::query("UPDATE users SET show_nsfw = 1 WHERE id = 'admin-id'")
            .execute(&pool)
            .await
            .unwrap();
        const ORIGIN: &str = r#"{ chapterOrigin(chapterId: "6") {
            sourceId extension { pkgName repoUrl apkName versionCode lang } } }"#;

        // Before: the bug's second symptom — no extension to install.
        let r = exec(&s, ORIGIN, None, "1.1.1.1").await;
        assert!(r.errors.is_empty(), "{:?}", r.errors);
        assert!(
            data_json(&r).contains(r#""extension":null"#),
            "{}",
            data_json(&r)
        );

        for mutation in ["installExtension", "updateExtension"] {
            sqlx::query("DELETE FROM source_extension")
                .execute(&pool)
                .await
                .unwrap();
            let r = exec(
                &s,
                &format!(r#"mutation {{ {mutation}(pkgName: "pkg.adult") {{ pkgName }} }}"#),
                Some("admintok"),
                "1.1.1.1",
            )
            .await;
            assert!(r.errors.is_empty(), "{mutation}: {:?}", r.errors);
            assert_eq!(
                recorded_source_nsfw(&pool, "1534").await,
                Some(1),
                "{mutation} records the source with the extension's NSFW flag"
            );
            let r = exec(&s, ORIGIN, None, "1.1.1.1").await;
            assert!(r.errors.is_empty(), "{:?}", r.errors);
            let j = data_json(&r);
            for want in [
                r#""sourceId":"1534""#,
                r#""pkgName":"pkg.adult""#,
                r#""repoUrl":"https://example.org/index.pb""#,
                r#""apkName":"adult-v7.apk""#,
                r#""versionCode":7"#,
            ] {
                assert!(j.contains(want), "{mutation}: missing {want} in {j}");
            }
        }

        // An engine that installs but cannot list its extensions: the install stands.
        let engine = crate::suwayomi::testsrv::spawn_status(
            200,
            "application/json",
            br#"{"data":{"updateExtension":{"extension":{"pkgName":"pkg.adult","name":"Adult",
                "lang":"en","versionName":"1.4.7","isInstalled":true,"hasUpdate":false,
                "isNsfw":false,"iconUrl":null,"repo":null}}}}"#
                .to_vec(),
            Duration::ZERO,
        )
        .await;
        let (s, pool, _) = setup_with_engine(100, &engine.base_url).await;
        sqlx::query("UPDATE users SET show_nsfw = 1 WHERE id = 'admin-id'")
            .execute(&pool)
            .await
            .unwrap();
        let r = exec(
            &s,
            r#"mutation { installExtension(pkgName: "pkg.adult") { pkgName } }"#,
            Some("admintok"),
            "1.1.1.1",
        )
        .await;
        assert!(
            r.errors.is_empty(),
            "record failure failed the install: {:?}",
            r.errors
        );
        assert_eq!(recorded_source_nsfw(&pool, "1534").await, None);
    }

    /// `markSourceNsfw(true)` used to write only `work.is_nsfw_override` on the works
    /// the source ALREADY had, and remember nothing: a series added from the source
    /// afterwards came in safe whenever the engine did not flag the source itself. The
    /// decision is now kept per source, survives the record pass, and is forgotten by
    /// `markSourceNsfw(false)`.
    #[tokio::test]
    async fn mark_source_nsfw_sticks_for_series_added_later() {
        let (s, pool, st) = setup_with_state(100).await;
        // The engine calls source "1534" safe; that is what the record pass stores.
        let safe = crate::catalog::SourceExtensionInput {
            pkg_name: "pkg.x".into(),
            repo_url: "https://r".into(),
            apk_name: None,
            version_code: Some(1),
            lang: Some("en".into()),
            is_nsfw: false,
        };
        crate::catalog::upsert_source_extension(&pool, "1534", &safe)
            .await
            .unwrap();
        let before = add_source_series_checked(
            &st,
            &suwayomi_manga(601, "Harbour Lights", &["Action"], "1534"),
            None,
            false,
        )
        .await
        .unwrap();

        let r = exec(
            &s,
            r#"mutation { markSourceNsfw(sourceId:"1534", isNsfw:true) }"#,
            Some("admintok"),
            "1.1.1.1",
        )
        .await;
        assert!(r.errors.is_empty(), "{:?}", r.errors);
        assert!(data_json(&r).contains(r#""markSourceNsfw":1"#));
        // The record pass runs again and re-writes the row from the engine: still safe.
        crate::catalog::upsert_source_extension(&pool, "1534", &safe)
            .await
            .unwrap();
        assert_eq!(recorded_source_nsfw(&pool, "1534").await, Some(0));

        // A series added AFTER the admin's decision, with no adult genre of its own.
        let after = add_source_series_checked(
            &st,
            &suwayomi_manga(602, "Winter Ferry", &["Action"], "1534"),
            None,
            false,
        )
        .await
        .unwrap();
        // ...and one from another source, which the pin must not touch.
        crate::catalog::upsert_source_extension(&pool, "9999", &safe)
            .await
            .unwrap();
        let other = add_source_series_checked(
            &st,
            &suwayomi_manga(603, "Salt Road", &["Action"], "9999"),
            None,
            false,
        )
        .await
        .unwrap();

        async fn flags(pool: &Database, id: &str) -> (i64, Option<i64>) {
            sqlx::query_as("SELECT is_nsfw, is_nsfw_override FROM work WHERE id = ?")
                .bind(id)
                .fetch_one(pool)
                .await
                .unwrap()
        }
        assert_eq!(flags(&pool, &before.work_id).await, (0, Some(1)));
        assert_eq!(
            flags(&pool, &after.work_id).await,
            (1, Some(1)),
            "a later series from a pinned source is pinned like the earlier ones"
        );
        assert_eq!(flags(&pool, &other.work_id).await, (0, None));
        for id in [&before.work_id, &after.work_id] {
            let q = format!(r#"{{ aggregatedChapters(workId: "{id}") {{ number }} }}"#);
            let r = exec(&s, &q, None, "1.1.1.1").await;
            assert_eq!(
                r.errors.first().map(|e| e.message.as_str()),
                Some("No such work"),
                "pinned source's work {id} served to a signed-out visitor"
            );
        }

        // Undo forgets the decision: the next series is judged by the engine again.
        let r = exec(
            &s,
            r#"mutation { markSourceNsfw(sourceId:"1534", isNsfw:false) }"#,
            Some("admintok"),
            "1.1.1.1",
        )
        .await;
        assert!(r.errors.is_empty(), "{:?}", r.errors);
        let unpinned = add_source_series_checked(
            &st,
            &suwayomi_manga(604, "Paper Kites", &["Action"], "1534"),
            None,
            false,
        )
        .await
        .unwrap();
        assert_eq!(flags(&pool, &unpinned.work_id).await, (0, None));
        assert_eq!(flags(&pool, &before.work_id).await, (0, None));
    }

    async fn exec(
        schema: &ApiSchema,
        query: &str,
        token: Option<&str>,
        ip: &str,
    ) -> async_graphql::Response {
        let req = async_graphql::Request::new(query)
            .data(RequestAuth(token.map(|t| t.to_string())))
            .data(ClientIp(Some(ip.to_string())))
            .data(RequestUserCache::default())
            .data(RequestLibraryCache::default());
        schema.execute(req).await
    }

    /// `ensure_utc_offset` must be a NO-OP on anything already carrying an offset — and
    /// in particular must not be fooled by the `-` separators in the DATE part into
    /// thinking a naive value already has a negative UTC offset. Every dated
    /// `series_scan_state` row in production is the `+00:00` case, so the pass-through
    /// arm is the one that actually runs; the appending arm guards future writers.
    #[test]
    fn ensure_utc_offset_appends_only_when_missing() {
        for already in [
            "2026-07-26T13:48:54.108583013+00:00",
            "2026-07-26T13:48:54Z",
            "2026-07-26T08:48:54-05:00",
        ] {
            assert_eq!(ensure_utc_offset(already), already, "must pass through");
        }
        // Naive: the date's own hyphens must not be read as an offset.
        assert_eq!(
            ensure_utc_offset("2026-07-26T13:58:51.705034"),
            "2026-07-26T13:58:51.705034Z"
        );
        assert_eq!(
            ensure_utc_offset("2026-07-26T13:58:51"),
            "2026-07-26T13:58:51Z"
        );
        // Surrounding whitespace is trimmed rather than baked into the output.
        assert_eq!(
            ensure_utc_offset("  2026-07-26T13:58:51  "),
            "2026-07-26T13:58:51Z"
        );
        // Parseable by the same reader-side path that was reading these as local time.
        assert!(
            chrono::DateTime::parse_from_rfc3339(&ensure_utc_offset("2026-07-26T13:58:51")).is_ok(),
            "output must be valid RFC 3339"
        );
    }

    fn first_error(resp: &async_graphql::Response) -> String {
        resp.errors
            .first()
            .map(|e| e.message.clone())
            .unwrap_or_default()
    }

    #[tokio::test]
    async fn updates_feed_is_newest_first_and_reports_new_chapter_time() {
        // "Latest Updates" ORDERS by the REAL upstream release time of the newest
        // chapter (`latestChapterAt`, from `suwayomi_series.latest_chapter_at`,
        // migration 0050) — which is the timestamp the reader prints on every card.
        // The scanner's DETECTION time decides membership and is exposed separately as
        // `detectedAt`; it must not be written over `updatedAt`/`latestChapterAt`
        // (doing so made the feed claim a chapter uploaded days ago had landed an hour
        // ago) and it must NOT drive the order either.
        //
        // The two clocks are deliberately INVERTED in this fixture: the row detected
        // FIRST has the NEWER release time. Ordering by detection and ordering by
        // release therefore give opposite answers, so the assertions below can tell
        // the two apart. (They previously agreed, which made this test pass either way.)
        let (s, pool) = setup_full(100).await;
        for (id, title, new_at, latest_ms) in [
            (
                10_i64,
                // detected EARLIER, released LATER -> must sort FIRST.
                "Older Detection Newer Release",
                "2026-07-01T00:00:00+00:00",
                "1751328000000",
            ),
            (
                20,
                // detected LATER, released EARLIER -> must sort SECOND.
                "Newer Detection Older Release",
                "2026-07-10T00:00:00+00:00",
                "1748736000000",
            ),
        ] {
            sqlx::query(
                "INSERT INTO suwayomi_series \
                   (id, title, status, source_id, chapter_count, in_library, latest_chapter_at, updated_at) \
                 VALUES (?, ?, 'ONGOING', 'src', 5, 1, ?, '2026-07-15T00:00:00+00:00')",
            )
            .bind(id)
            .bind(title)
            .bind(latest_ms)
            .execute(&pool)
            .await
            .unwrap();
            sqlx::query(
                "INSERT INTO series_scan_state \
                   (series_id, avg_interval_hours, known_chapter_count, last_new_chapter_at, updated_at) \
                 VALUES (?, 0, 5, ?, '2026-07-15T00:00:00+00:00')",
            )
            .bind(id.to_string())
            .bind(new_at)
            .execute(&pool)
            .await
            .unwrap();
        }

        let r = exec(
            &s,
            r#"{ updates { items { id title updatedAt detectedAt latestChapterAt } total } }"#,
            None,
            "1.2.3.4",
        )
        .await;
        assert!(r.errors.is_empty(), "updates failed: {:?}", r.errors);
        let data = r.data.into_json().unwrap();
        let items = data["updates"]["items"].as_array().unwrap();
        assert_eq!(items.len(), 2);
        // Newest RELEASE time first. The earlier-detected row wins because its chapter
        // is the newer one — the whole point of the ordering.
        assert_eq!(
            items[0]["title"],
            serde_json::json!("Older Detection Newer Release")
        );
        assert_eq!(
            items[1]["title"],
            serde_json::json!("Newer Detection Older Release")
        );
        // `detectedAt` still carries the detection time, and is now plainly NOT the
        // sort key: it ascends down the page while the feed descends by release time.
        assert_eq!(
            items[0]["detectedAt"],
            serde_json::json!("2026-07-01T00:00:00+00:00")
        );
        assert_eq!(
            items[1]["detectedAt"],
            serde_json::json!("2026-07-10T00:00:00+00:00")
        );
        // ...and `updatedAt` stays HONEST (the source's own last-touch stamp), no
        // longer overwritten with our detection time.
        assert_ne!(
            items[0]["updatedAt"],
            serde_json::json!("2026-07-01T00:00:00+00:00"),
            "updatedAt must not be overwritten with the detection time"
        );
        // `latestChapterAt` is the stored upstream newest-chapter time, not the poll —
        // and it descends, because it IS the sort key.
        assert_eq!(
            items[0]["latestChapterAt"],
            serde_json::json!(to_iso(Some("1751328000000")).unwrap())
        );
        assert_eq!(
            items[1]["latestChapterAt"],
            serde_json::json!(to_iso(Some("1748736000000")).unwrap())
        );
    }

    /// Seed one Updates-feed member: the library `suwayomi_series` row that carries the
    /// release-time sort key, plus the `series_scan_state` row that grants membership.
    ///
    /// `latest_ms` is epoch-millis TEXT (as migration 0050 stores it) or `None` for a
    /// series with no datable chapter; `detected_at` is the ISO-8601 detection stamp.
    /// `in_library` is a parameter because the difference between 0 and 1 is exactly what
    /// `updates_total_matches_paged_row_count` is about.
    async fn seed_feed_member(
        pool: &Database,
        id: i64,
        title: &str,
        latest_ms: Option<&str>,
        detected_at: &str,
        in_library: i64,
    ) {
        sqlx::query(
            "INSERT INTO suwayomi_series \
               (id, title, status, source_id, chapter_count, in_library, latest_chapter_at, updated_at) \
             VALUES (?, ?, 'ONGOING', 'src', 5, ?, ?, '2026-07-15T00:00:00+00:00')",
        )
        .bind(id)
        .bind(title)
        .bind(in_library)
        .bind(latest_ms)
        .execute(pool)
        .await
        .unwrap();
        sqlx::query(
            "INSERT INTO series_scan_state \
               (series_id, avg_interval_hours, known_chapter_count, last_new_chapter_at, updated_at) \
             VALUES (?, 0, 5, ?, '2026-07-15T00:00:00+00:00')",
        )
        .bind(id.to_string())
        .bind(detected_at)
        .execute(pool)
        .await
        .unwrap();
    }

    /// THE `updates` TOTAL MEMO — correct per AUDIENCE, and invalidated by the rebuild.
    ///
    /// The F3-gate removal took this COUNT from 13.8 ms to 53.4 ms warm (2,060 → 14,169
    /// candidate rows, and the NSFW subquery stopped short-circuiting behind the gate), so it
    /// is memoized. A memo on a viewer-dependent number has one failure mode that matters far
    /// more than staleness: serving one audience's answer to the other. Anonymous and
    /// opted-in totals genuinely differ (13,726 vs 14,169 on the snapshot), and handing the
    /// larger to an anonymous viewer is a pager promising pages the NSFW gate will never
    /// return.
    ///
    /// This drives `updates_total` with a REAL ttl — `COUNT_TTL` is `ZERO` under `cfg(test)`,
    /// so the resolver-level tests never touch the memo and could not catch any of this.
    #[tokio::test]
    async fn the_updates_total_memo_is_keyed_by_audience_and_cleared_by_the_rebuild() {
        let (_s, pool) = setup_full(100).await;
        // One SFW series and one NSFW one, both enrolled, in library and dated.
        seed_feed_member(
            &pool,
            1,
            "Safe",
            Some("1752969600000"),
            "2026-07-26T11:00:00+00:00",
            1,
        )
        .await;
        seed_feed_member(
            &pool,
            2,
            "Adult",
            Some("1752105600000"),
            "2026-07-26T11:00:00+00:00",
            1,
        )
        .await;
        let nsfw_work = crate::catalog::create_work(
            &pool,
            &crate::catalog::WorkInput {
                primary_title: Some("Adult".into()),
                is_nsfw: true,
                ..Default::default()
            },
        )
        .await
        .unwrap();
        crate::catalog::upsert_source_series(
            &pool, &nsfw_work, "suwayomi", "src", "2", None, false,
        )
        .await
        .unwrap();

        // The SQL the resolver builds, byte for byte.
        const DETECTED: &str = "EXISTS ( \
             SELECT 1 FROM series_scan_state sss \
             WHERE sss.series_id = CAST(suwayomi_series.id AS TEXT))";
        const NSFW_FILTER: &str = "(? = 1 OR NOT EXISTS ( \
             SELECT 1 FROM source_series ss JOIN work w ON w.id = ss.work_id \
             WHERE ss.source_type = 'suwayomi' AND ss.source_key = CAST(suwayomi_series.id AS TEXT) \
               AND COALESCE(w.is_nsfw_override, w.is_nsfw) = 1))";
        let count_sql = format!(
            "SELECT COUNT(*) FROM suwayomi_series \
             WHERE in_library = 1 AND {DETECTED} AND {NSFW_FILTER}"
        );
        let ttl = std::time::Duration::from_secs(60);
        let uncached = |show_nsfw: bool| {
            let sql = count_sql.clone();
            let pool = pool.clone();
            async move {
                sqlx::query_scalar::<_, i64>(&sql)
                    .bind(show_nsfw as i64)
                    .fetch_one(&pool)
                    .await
                    .unwrap()
            }
        };

        crate::browse::clear_count_cache();
        // Cold: both audiences must equal the uncached query.
        assert_eq!(uncached(false).await, 1, "the fixture must actually differ");
        assert_eq!(uncached(true).await, 2, "…across the two audiences");
        assert_eq!(
            updates_total(&pool, &count_sql, false, ttl).await.unwrap(),
            1
        );
        assert_eq!(
            updates_total(&pool, &count_sql, true, ttl).await.unwrap(),
            2
        );
        // WARM, and the load-bearing assertion: the anonymous viewer must not be served the
        // opted-in total now that both are cached. A single un-keyed entry fails here.
        assert_eq!(
            updates_total(&pool, &count_sql, false, ttl).await.unwrap(),
            1,
            "an anonymous viewer must never be served the opted-in total"
        );
        assert_eq!(
            updates_total(&pool, &count_sql, true, ttl).await.unwrap(),
            2,
            "…nor the reverse"
        );
        assert_ne!(
            updates_count_key(false),
            updates_count_key(true),
            "the two audiences must not share a key"
        );

        // The memo really is serving: change the data underneath it and watch it NOT move.
        // (Staleness is the accepted trade — see `updates_total`.)
        sqlx::query("UPDATE suwayomi_series SET in_library = 0 WHERE id = 1")
            .execute(&pool)
            .await
            .unwrap();
        assert_eq!(uncached(false).await, 0, "the data really did change");
        assert_eq!(
            updates_total(&pool, &count_sql, false, ttl).await.unwrap(),
            1,
            "a memoized total is allowed to be stale — that is what buys the 53 ms"
        );

        // …and `clear_count_cache` — which `catalog::refresh_browse_catalogue` calls at the
        // end of every rebuild, i.e. the event that changes this number — closes it.
        crate::browse::clear_count_cache();
        assert_eq!(
            updates_total(&pool, &count_sql, false, ttl).await.unwrap(),
            0,
            "the rebuild's cache clear must invalidate the updates total too"
        );
        assert_eq!(
            updates_total(&pool, &count_sql, true, ttl).await.unwrap(),
            1,
            "…for both audiences"
        );
        // Leave nothing behind: the memo is a process-wide static and every other test in
        // this binary shares it.
        crate::browse::clear_count_cache();
    }

    /// THE F3 GATE'S REMOVAL, on the `updates` RESOLVER (owner-approved 2026-07-31).
    ///
    /// `updates` kept its own copy of `AND sss.last_new_chapter_at IS NOT NULL` after both
    /// feed WRITERS dropped it, and it is not dead code: the reader's home "Latest Updates"
    /// row calls this resolver while `/updates` pages `updatesFeed`. So the two surfaces
    /// disagreed about who is in the feed — 10,966 works against 1,820 (§8h).
    ///
    /// The three membership rules that REMAIN are each asserted here, because the widening
    /// is only safe if it widens exactly one of them:
    ///
    /// * ENROLLED — a `series_scan_state` row must exist. Almost every in-library series has
    ///   one (snapshot: 14,169 of 14,182); the 13 that do not are series the scanner has
    ///   never touched, and `detectedAt`/`latestChapterAt` come from that side of the house.
    /// * IN LIBRARY — the feed is the reader's library, unchanged.
    /// * The DETECTION STAMP is no longer consulted. A first observation is a baseline and
    ///   deliberately never stamps `last_new_chapter_at` (`scanner::record_scan`), so a
    ///   series we mirrored completely and never caught mid-update was locked out forever.
    ///
    /// If a later change re-adds the stamp test, "Never Detected" disappears and this fails.
    /// Home's `discovery` rows must carry the newest chapter's LABEL, not just a count.
    ///
    /// This regressed silently once already: `assemble_series` hardcodes
    /// `latest_chapter: None` (correctly — a wire manga has only a count, and inventing a
    /// label there is F4), and nothing refilled it on the batch path. The result was
    /// `discovery` returning `latestChapter: null` for **every** item while `search`
    /// returned it for all of them, so one work read "115 ch" on home and
    /// "115 ch · Ch. 90" on Browse.
    ///
    /// The fixture deliberately makes count and label DISAGREE (7 chapters, newest
    /// numbered 90). A regression that reached for the count would return "7" and fail
    /// here rather than quietly printing a count under a "Ch." label.
    #[tokio::test]
    async fn discovery_rows_carry_the_latest_chapter_label_not_the_count() {
        let (_s, pool) = setup_full(100).await;
        sqlx::query(
            "INSERT INTO work (id, primary_title, is_nsfw, created_at, updated_at) \
             VALUES ('w_home', 'Partial Mirror', 0, '2020-01-01T00:00:00Z', \
                     '2020-01-01T00:00:00Z')",
        )
        .execute(&pool)
        .await
        .unwrap();
        sqlx::query(
            "INSERT INTO source_series \
               (id, work_id, source_type, source_id, source_key, created_at) \
             VALUES ('ss_home', 'w_home', 'suwayomi', 'src', '77', 0)",
        )
        .execute(&pool)
        .await
        .unwrap();
        // count 7 vs newest label "90" — a partial mirror, the case the card exists for.
        sqlx::query(
            "INSERT INTO browse_catalogue \
               (work_id, reader_id, title, content_rating, is_nsfw, en_chapter_count, \
                latest_chapter, created_at) \
             VALUES ('w_home', '77', 'Partial Mirror', 'safe', 0, 7, '90', 0)",
        )
        .execute(&pool)
        .await
        .unwrap();

        let got = suwayomi_latest_chapter_label_batch(&pool, &["77".to_string()]).await;
        assert_eq!(
            got.get("77").map(String::as_str),
            Some("90"),
            "home's batch path must supply the ledger's chapter LABEL for a mapped series"
        );
        assert_ne!(
            got.get("77").map(String::as_str),
            Some("7"),
            "a count must never be served as the chapter number — that is F4"
        );

        // A series with no browse_catalogue row stays absent, so the caller keeps `None`
        // and the card prints the count alone rather than "Ch. undefined".
        let missing = suwayomi_latest_chapter_label_batch(&pool, &["404".to_string()]).await;
        assert!(
            missing.is_empty(),
            "unmapped ids must be absent, not empty-string"
        );
    }

    #[tokio::test]
    async fn updates_admits_a_series_our_scanner_never_saw_change() {
        let (s, pool) = setup_full(100).await;
        // Detected, in library — admitted before and after. The NEWEST release, so it leads.
        seed_feed_member(
            &pool,
            1,
            "Detected",
            Some("1752969600000"),
            "2026-07-26T11:00:00+00:00",
            1,
        )
        .await;
        // Enrolled, in library, dated — but never seen to CHANGE. This is the ~9,851-series
        // cohort the gate excluded.
        sqlx::query(
            "INSERT INTO suwayomi_series \
               (id, title, status, source_id, chapter_count, in_library, latest_chapter_at, updated_at) \
             VALUES (2, 'Never Detected', 'ONGOING', 'src', 5, 1, '1752105600000', \
                     '2026-07-15T00:00:00+00:00')",
        )
        .execute(&pool)
        .await
        .unwrap();
        sqlx::query(
            "INSERT INTO series_scan_state \
               (series_id, avg_interval_hours, known_chapter_count, last_new_chapter_at, updated_at) \
             VALUES ('2', 0, 5, NULL, '2026-07-15T00:00:00+00:00')",
        )
        .execute(&pool)
        .await
        .unwrap();
        // Detected and freshly released, but NOT in the library — still excluded.
        seed_feed_member(
            &pool,
            3,
            "Out Of Library",
            Some("1753969600000"),
            "2026-07-26T11:00:00+00:00",
            0,
        )
        .await;
        // In library and freshly released, but never enrolled with the scanner at all — no
        // `series_scan_state` row, so still excluded. This is the half of the predicate the
        // change KEEPS, and the reason the `INDEXED BY` hint could be dropped rather than
        // re-pointed: what is left is a pure equality on the table's primary key.
        sqlx::query(
            "INSERT INTO suwayomi_series \
               (id, title, status, source_id, chapter_count, in_library, latest_chapter_at, updated_at) \
             VALUES (4, 'Never Enrolled', 'ONGOING', 'src', 5, 1, '1753969600000', \
                     '2026-07-15T00:00:00+00:00')",
        )
        .execute(&pool)
        .await
        .unwrap();

        let r = exec(
            &s,
            r#"{ updates { items { title detectedAt } total } }"#,
            None,
            "1.2.3.4",
        )
        .await;
        assert!(r.errors.is_empty(), "updates failed: {:?}", r.errors);
        let data = r.data.into_json().unwrap();
        let items = data["updates"]["items"].as_array().unwrap();
        let titles: Vec<&str> = items.iter().map(|i| i["title"].as_str().unwrap()).collect();
        assert_eq!(
            titles,
            vec!["Detected", "Never Detected"],
            "the undetected series joins the feed, ordered by its own release clock"
        );
        assert_eq!(data["updates"]["total"], serde_json::json!(2));
        // And it reports an HONEST `detectedAt`: we have never detected a change on it, so
        // the field is null rather than borrowing the release time.
        assert!(
            items[1]["detectedAt"].is_null(),
            "detectedAt must stay null for a series we never saw change: {:?}",
            items[1]
        );
    }

    /// REGRESSION GUARD for the Updates feed's sort key.
    ///
    /// The feed ordered by `series_scan_state.last_new_chapter_at` — the moment OUR
    /// scanner noticed the chapter — while the reader labelled every card with
    /// `latestChapterAt`, the real upstream release time. Those clocks are uncorrelated:
    /// measured against production, the top card of the feed read "36d" and position 10
    /// read "74d". A chapter released six months ago that we happened to poll a minute
    /// ago outranked one released this morning.
    ///
    /// The assertion is deliberately made on `latestChapterAt` — the field the reader
    /// RENDERS — and not on an id order, so it keeps holding if the fixture or the
    /// tiebreaker changes. Detection order here is the exact REVERSE of release order,
    /// so the old behaviour cannot pass.
    #[tokio::test]
    async fn updates_orders_by_release_time_not_detection() {
        let (s, pool) = setup_full(100).await;
        // (id, title, latest_chapter_at millis, detected_at)
        // Release order:   B (Jul 20) > A (Jul 10) > C (Jul 01)
        // Detection order: C (13:00)  > A (12:00)  > B (11:00)   <- exactly reversed
        for (id, title, latest_ms, detected) in [
            (
                1_i64,
                "Middle Release",
                "1752105600000", // 2025-07-10
                "2026-07-26T12:00:00+00:00",
            ),
            (
                2,
                "Newest Release",
                "1752969600000", // 2025-07-20
                "2026-07-26T11:00:00+00:00",
            ),
            (
                3,
                "Oldest Release",
                "1751328000000", // 2025-07-01
                "2026-07-26T13:00:00+00:00",
            ),
        ] {
            seed_feed_member(&pool, id, title, Some(latest_ms), detected, 1).await;
        }

        let r = exec(
            &s,
            r#"{ updates { items { title detectedAt latestChapterAt } total } }"#,
            None,
            "1.2.3.4",
        )
        .await;
        assert!(r.errors.is_empty(), "updates failed: {:?}", r.errors);
        let data = r.data.into_json().unwrap();
        let items = data["updates"]["items"].as_array().unwrap();
        assert_eq!(
            items.len(),
            3,
            "all three are library members with detections"
        );
        assert_eq!(data["updates"]["total"], serde_json::json!(3));

        // The visible label must be monotonically NON-INCREASING down the page.
        let released: Vec<&str> = items
            .iter()
            .map(|i| i["latestChapterAt"].as_str().expect("latestChapterAt set"))
            .collect();
        let mut sorted = released.clone();
        sorted.sort_unstable_by(|a, b| b.cmp(a));
        assert_eq!(
            released, sorted,
            "the feed must descend by the release time it displays, got {released:?}"
        );
        // And the fixture really did disagree: ordering by detection would have put
        // "Oldest Release" first. (If this ever stops holding the test has gone blind.)
        assert_eq!(items[0]["title"], serde_json::json!("Newest Release"));
        assert_eq!(items[2]["title"], serde_json::json!("Oldest Release"));
        let detected: Vec<&str> = items
            .iter()
            .map(|i| i["detectedAt"].as_str().expect("detectedAt set"))
            .collect();
        assert_ne!(
            detected,
            {
                let mut d = detected.clone();
                d.sort_unstable_by(|a, b| b.cmp(a));
                d
            },
            "fixture is not exercising the bug: detection order already matches release order"
        );
    }

    /// A series with NO release time sorts LAST, and is neither dropped nor promoted.
    ///
    /// This is the row a `COALESCE(latest_chapter_at, last_new_chapter_at)` would have
    /// put FIRST: the two columns are stored in different encodings (13-digit epoch
    /// millis TEXT vs ISO-8601 TEXT), so under BINARY collation every '2...' ISO
    /// fallback sorts above every '1...' epoch value. Its detection time here is the
    /// most recent in the fixture, so a fallback to detection time would also float it
    /// to the top.
    ///
    /// It must still be PRESENT (it is a genuine library member with a genuine
    /// detection) and still counted in `total` — the ordering says "we don't know when
    /// this was released", not "this doesn't exist".
    #[tokio::test]
    async fn updates_sorts_null_latest_chapter_at_last() {
        let (s, pool) = setup_full(100).await;
        seed_feed_member(
            &pool,
            1,
            "Has Release Time",
            Some("1751328000000"), // 2025-07-01
            "2026-07-01T00:00:00+00:00",
            1,
        )
        .await;
        seed_feed_member(
            &pool,
            2,
            "No Release Time",
            None,
            // The most recent detection in the fixture — the COALESCE trap.
            "2026-07-26T23:59:59+00:00",
            1,
        )
        .await;

        let r = exec(
            &s,
            r#"{ updates { items { title detectedAt latestChapterAt } total hasNextPage } }"#,
            None,
            "1.2.3.4",
        )
        .await;
        assert!(r.errors.is_empty(), "updates failed: {:?}", r.errors);
        let data = r.data.into_json().unwrap();
        let items = data["updates"]["items"].as_array().unwrap();
        assert_eq!(
            items.len(),
            2,
            "the undated row is not dropped from the page"
        );
        assert_eq!(
            data["updates"]["total"],
            serde_json::json!(2),
            "the undated row is still counted"
        );
        assert_eq!(items[0]["title"], serde_json::json!("Has Release Time"));
        assert_eq!(
            items[1]["title"],
            serde_json::json!("No Release Time"),
            "a row with no release time belongs at the BOTTOM, not the top"
        );
        // `latestChapterAt` is `String!` in the schema, so "no dated chapter" is the
        // EMPTY STRING, not null. Either way the point is that no time is invented for
        // it — in particular the detection time is not substituted in.
        assert_eq!(
            items[1]["latestChapterAt"],
            serde_json::json!(""),
            "no release time must be reported as empty, not invented"
        );
        // Membership data survives: this is a sort change, not a data removal.
        assert_eq!(
            items[1]["detectedAt"],
            serde_json::json!("2026-07-26T23:59:59+00:00")
        );
    }

    /// The `id DESC` tiebreaker gives the feed a TOTAL order, so paging cannot repeat or
    /// skip rows.
    ///
    /// `latest_chapter_at` ties are common, not theoretical: production has 34 groups of
    /// rows sharing one timestamp, covering 143 of the 1,316 feed members (whole batches
    /// of series get the same coarse upstream date). With no tiebreaker, SQLite is free
    /// to return tied rows in any order, and it need not be the SAME order for the
    /// OFFSET-0 and OFFSET-20 executions — so a row could appear on both pages while
    /// another appeared on neither. This test seeds `PAGE_SIZE + 5` rows sharing ONE
    /// timestamp, which is nothing BUT a tie, and would flap without the tiebreaker.
    #[tokio::test]
    async fn updates_tiebreaks_on_id_without_duplicates_across_pages() {
        let (s, pool) = setup_full(100).await;
        let n = PAGE_SIZE + 5;
        for id in 1..=n {
            seed_feed_member(
                &pool,
                id,
                &format!("Tied Series {id:02}"),
                Some("1751328000000"), // every row: the SAME release time
                "2026-07-20T00:00:00+00:00",
                1,
            )
            .await;
        }

        let ids_on = |page: i32| {
            let s = &s;
            async move {
                let r = exec(
                    s,
                    &format!("{{ updates(page: {page}) {{ items {{ id }} total hasNextPage }} }}"),
                    None,
                    "1.2.3.4",
                )
                .await;
                assert!(r.errors.is_empty(), "updates failed: {:?}", r.errors);
                let data = r.data.into_json().unwrap();
                let ids: Vec<i64> = data["updates"]["items"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|i| i["id"].as_str().unwrap().parse().unwrap())
                    .collect();
                (ids, data["updates"]["total"].as_i64().unwrap())
            }
        };
        let (p1, total) = ids_on(1).await;
        let (p2, _) = ids_on(2).await;
        assert_eq!(total, n, "total counts every seeded member");
        assert_eq!(p1.len() as i64, PAGE_SIZE, "page 1 is full");
        assert_eq!(p2.len() as i64, n - PAGE_SIZE, "page 2 holds the remainder");

        // Disjoint: no id may be served twice.
        let set1: std::collections::HashSet<i64> = p1.iter().copied().collect();
        let set2: std::collections::HashSet<i64> = p2.iter().copied().collect();
        assert!(
            set1.is_disjoint(&set2),
            "pages overlap: {:?}",
            set1.intersection(&set2).collect::<Vec<_>>()
        );
        // And gapless: together they are exactly the seeded set.
        let mut seen: Vec<i64> = set1.union(&set2).copied().collect();
        seen.sort_unstable();
        assert_eq!(
            seen,
            (1..=n).collect::<Vec<i64>>(),
            "paging lost or invented rows across the tie"
        );
        // The tiebreaker is `id DESC`, so page 1 is the high ids.
        assert_eq!(p1[0], n, "highest id first within a tie group");
    }

    /// `total` must count EXACTLY the rows the pages can return.
    ///
    /// `total` used to count every dated `series_scan_state` row while the page query is
    /// now driven from `suwayomi_series WHERE in_library = 1`. Scan state outlives
    /// library membership (removing a series from the library does not delete its scan
    /// row), so a stale row inflated `total` and with it `hasNextPage` and the reader's
    /// page count — offering a page that comes back empty.
    #[tokio::test]
    async fn updates_total_matches_paged_row_count() {
        let (s, pool) = setup_full(100).await;
        seed_feed_member(
            &pool,
            1,
            "In Library",
            Some("1751328000000"),
            "2026-07-20T00:00:00+00:00",
            1,
        )
        .await;
        // Same shape, same detection — but no longer a library member.
        seed_feed_member(
            &pool,
            2,
            "Dropped From Library",
            Some("1752969600000"), // NEWER release: would be first if it counted at all
            "2026-07-21T00:00:00+00:00",
            0,
        )
        .await;

        let r = exec(
            &s,
            r#"{ updates { items { id title } total hasNextPage } }"#,
            None,
            "1.2.3.4",
        )
        .await;
        assert!(r.errors.is_empty(), "updates failed: {:?}", r.errors);
        let data = r.data.into_json().unwrap();
        let items = data["updates"]["items"].as_array().unwrap();
        let titles: Vec<&str> = items.iter().map(|i| i["title"].as_str().unwrap()).collect();
        assert_eq!(
            titles,
            vec!["In Library"],
            "a series that left the library must not appear"
        );
        assert_eq!(
            data["updates"]["total"],
            serde_json::json!(1),
            "total must not count the row the pages cannot return"
        );
        assert_eq!(data["updates"]["hasNextPage"], serde_json::json!(false));
        assert_eq!(
            items.len() as i64,
            data["updates"]["total"].as_i64().unwrap(),
            "single-page feed: items and total must agree exactly"
        );
    }

    /// A cheap pin on the OTHER updates feed, which is already correct.
    ///
    /// `canonicalUpdates` reads `feed_updates.latest_at` — the real chapter publish time
    /// — and has always ordered by it. That is now the SAME contract the Suwayomi
    /// `updates` feed follows ("sort by the clock you display"), and the two feeds are
    /// merged into one list client-side, so if this one ever drifted onto a different
    /// clock the merged Updates grid would silently interleave two orderings again. This
    /// asserts the alignment rather than assuming it.
    #[tokio::test]
    async fn canonical_updates_orders_by_latest_at() {
        let (s, pool) = setup_full(100).await;
        // `seed_canonical` publishes chapter `ch` at 2026-07-0{ch}, so the digit IS the
        // release date — seeded here in deliberately NON-descending order.
        seed_canonical(&pool, "md-mid", "Mid Release", false, "2").await;
        seed_canonical(&pool, "md-new", "New Release", false, "3").await;
        seed_canonical(&pool, "md-old", "Old Release", false, "1").await;
        crate::catalog::refresh_feed_updates(&pool).await.unwrap();

        let r = exec(
            &s,
            r#"{ canonicalUpdates { title latestAt } }"#,
            None,
            "1.2.3.4",
        )
        .await;
        assert!(
            r.errors.is_empty(),
            "canonicalUpdates failed: {:?}",
            r.errors
        );
        let data = r.data.into_json().unwrap();
        let rows = data["canonicalUpdates"].as_array().unwrap();
        assert_eq!(rows.len(), 3);
        let at: Vec<&str> = rows
            .iter()
            .map(|x| x["latestAt"].as_str().expect("latestAt is NOT NULL"))
            .collect();
        let mut sorted = at.clone();
        sorted.sort_unstable_by(|a, b| b.cmp(a));
        assert_eq!(at, sorted, "canonicalUpdates must descend by latestAt");
        let titles: Vec<&str> = rows.iter().map(|x| x["title"].as_str().unwrap()).collect();
        assert_eq!(titles, vec!["New Release", "Mid Release", "Old Release"]);
    }

    #[tokio::test]
    async fn comment_votes_and_notifications_flow() {
        let (s, _pool) = setup_full(100).await;
        // admin posts a root comment on series "s1".
        let r = exec(
            &s,
            r#"mutation { postComment(input: { targetType: "series", targetId: "s1", body: "hi", hasSpoiler: false }) { id likes myVote } }"#,
            Some("admintok"),
            "1.1.1.1",
        )
        .await;
        assert!(r.errors.is_empty(), "postComment: {:?}", r.errors);
        let cid = r.data.into_json().unwrap()["postComment"]["id"]
            .as_str()
            .unwrap()
            .to_string();

        // bob replies -> admin gets a 'reply' notification.
        let reply = format!(
            r#"mutation {{ postComment(input: {{ targetType: "series", targetId: "s1", parentId: "{cid}", body: "yo", hasSpoiler: false }}) {{ id }} }}"#
        );
        let r = exec(&s, &reply, Some("bobtok"), "2.2.2.2").await;
        assert!(r.errors.is_empty(), "reply: {:?}", r.errors);

        // bob likes admin's comment -> tally = 1 like, and admin gets a 'like_milestone'.
        let vote = format!(
            r#"mutation {{ voteComment(commentId: "{cid}", value: 1) {{ likes dislikes myVote }} }}"#
        );
        let r = exec(&s, &vote, Some("bobtok"), "2.2.2.2").await;
        assert!(r.errors.is_empty(), "vote: {:?}", r.errors);
        let v = r.data.into_json().unwrap()["voteComment"].clone();
        assert_eq!(v["likes"], serde_json::json!(1));
        assert_eq!(v["myVote"], serde_json::json!(1));

        // admin sees 2 unread notifications (reply + like_milestone).
        let r = exec(
            &s,
            r#"{ unreadNotificationCount notifications { kind count actor { username } commentExcerpt } }"#,
            Some("admintok"),
            "1.1.1.1",
        )
        .await;
        let d = r.data.into_json().unwrap();
        assert_eq!(d["unreadNotificationCount"], serde_json::json!(2));
        let notifs = d["notifications"].as_array().unwrap();
        let kinds: Vec<&str> = notifs.iter().map(|n| n["kind"].as_str().unwrap()).collect();
        assert!(kinds.contains(&"reply") && kinds.contains(&"like_milestone"));
        // The reply notification names the actor; the milestone carries the count.
        let reply_n = notifs.iter().find(|n| n["kind"] == "reply").unwrap();
        assert_eq!(reply_n["actor"]["username"], serde_json::json!("bob"));
        let ms = notifs
            .iter()
            .find(|n| n["kind"] == "like_milestone")
            .unwrap();
        assert_eq!(ms["count"], serde_json::json!(1));

        // The comments query shows the like tally; bob (the liker) sees myVote = 1.
        let r = exec(
            &s,
            r#"{ comments(targetType: "series", targetId: "s1") { items { id likes myVote } } }"#,
            Some("bobtok"),
            "2.2.2.2",
        )
        .await;
        let items = r.data.into_json().unwrap()["comments"]["items"]
            .as_array()
            .unwrap()
            .clone();
        let root = items
            .iter()
            .find(|c| c["id"] == serde_json::json!(cid))
            .unwrap();
        assert_eq!(root["likes"], serde_json::json!(1));
        assert_eq!(root["myVote"], serde_json::json!(1));

        // admin marks all read -> 0 unread.
        let r = exec(
            &s,
            r#"mutation { markNotificationsRead }"#,
            Some("admintok"),
            "1.1.1.1",
        )
        .await;
        assert!(r.errors.is_empty(), "markRead: {:?}", r.errors);
        let r = exec(
            &s,
            r#"{ unreadNotificationCount }"#,
            Some("admintok"),
            "1.1.1.1",
        )
        .await;
        assert_eq!(
            r.data.into_json().unwrap()["unreadNotificationCount"],
            serde_json::json!(0)
        );

        // bob (the replier/liker) is never notified of his own actions.
        let r = exec(
            &s,
            r#"{ unreadNotificationCount }"#,
            Some("bobtok"),
            "2.2.2.2",
        )
        .await;
        assert_eq!(
            r.data.into_json().unwrap()["unreadNotificationCount"],
            serde_json::json!(0)
        );
    }

    #[tokio::test]
    async fn vote_self_rejected_and_milestone_dedupes() {
        let (s, _pool) = setup_full(100).await;
        let r = exec(
            &s,
            r#"mutation { postComment(input: { targetType: "series", targetId: "s1", body: "x", hasSpoiler: false }) { id } }"#,
            Some("admintok"),
            "1.1.1.1",
        )
        .await;
        let cid = r.data.into_json().unwrap()["postComment"]["id"]
            .as_str()
            .unwrap()
            .to_string();

        // The author can't vote on their own comment.
        let self_vote =
            format!(r#"mutation {{ voteComment(commentId: "{cid}", value: 1) {{ likes }} }}"#);
        let r = exec(&s, &self_vote, Some("admintok"), "1.1.1.1").await;
        assert!(!r.errors.is_empty(), "self-vote must be rejected");

        // bob likes (milestone 1) → unlikes → re-likes: still exactly ONE like_milestone
        // (idempotent per comment+count), never a duplicate on re-crossing.
        let like =
            format!(r#"mutation {{ voteComment(commentId: "{cid}", value: 1) {{ likes }} }}"#);
        let clear =
            format!(r#"mutation {{ voteComment(commentId: "{cid}", value: 0) {{ likes }} }}"#);
        for q in [&like, &clear, &like] {
            let r = exec(&s, q, Some("bobtok"), "2.2.2.2").await;
            assert!(r.errors.is_empty(), "vote failed: {:?}", r.errors);
        }

        let r = exec(
            &s,
            r#"{ notifications { kind count } }"#,
            Some("admintok"),
            "1.1.1.1",
        )
        .await;
        let notifs = r.data.into_json().unwrap()["notifications"]
            .as_array()
            .unwrap()
            .clone();
        let milestones: Vec<_> = notifs
            .iter()
            .filter(|n| n["kind"] == "like_milestone")
            .collect();
        assert_eq!(
            milestones.len(),
            1,
            "milestone-1 must not duplicate on unlike/relike"
        );
        assert_eq!(milestones[0]["count"], serde_json::json!(1));
    }

    #[tokio::test]
    async fn chapter_comment_notification_resolves_owning_series() {
        // A reply on a CHAPTER thread notifies with the owning series id resolved, so
        // the client can deep-link to `/read/<seriesId>?ch=<chapterId>`.
        let (s, pool) = setup_full(100).await;
        // A numeric Suwayomi chapter 9001 belonging to series 500.
        sqlx::query(
            "INSERT INTO suwayomi_chapter (id, manga_id, name, chapter_number, page_count, updated_at) \
             VALUES (9001, 500, 'Ch 1', 1, 10, '2026-01-01T00:00:00Z')",
        )
        .execute(&pool)
        .await
        .unwrap();

        // admin comments on the chapter thread; bob replies.
        let r = exec(
            &s,
            r#"mutation { postComment(input: { targetType: "chapter", targetId: "9001", body: "root", hasSpoiler: false }) { id } }"#,
            Some("admintok"),
            "1.1.1.1",
        )
        .await;
        assert!(r.errors.is_empty(), "postComment: {:?}", r.errors);
        let cid = r.data.into_json().unwrap()["postComment"]["id"]
            .as_str()
            .unwrap()
            .to_string();
        let reply = format!(
            r#"mutation {{ postComment(input: {{ targetType: "chapter", targetId: "9001", parentId: "{cid}", body: "re", hasSpoiler: false }}) {{ id }} }}"#
        );
        let r = exec(&s, &reply, Some("bobtok"), "2.2.2.2").await;
        assert!(r.errors.is_empty(), "reply: {:?}", r.errors);

        // admin's notification carries targetType=chapter, targetId=9001, seriesId=500.
        let r = exec(
            &s,
            r#"{ notifications { kind targetType targetId seriesId } }"#,
            Some("admintok"),
            "1.1.1.1",
        )
        .await;
        let n = r.data.into_json().unwrap()["notifications"][0].clone();
        assert_eq!(n["kind"], serde_json::json!("reply"));
        assert_eq!(n["targetType"], serde_json::json!("chapter"));
        assert_eq!(n["targetId"], serde_json::json!("9001"));
        assert_eq!(n["seriesId"], serde_json::json!("500"));
    }

    #[tokio::test]
    async fn my_comments_lists_own_comments_with_tallies_and_targets() {
        let (s, pool) = setup_full(100).await;
        // Signed out → an empty page, never an error.
        let r = exec(
            &s,
            r#"{ myComments { items { id } total } }"#,
            None,
            "1.1.1.1",
        )
        .await;
        assert!(r.errors.is_empty(), "unexpected: {:?}", r.errors);
        let d = r.data.into_json().unwrap();
        assert_eq!(d["myComments"]["total"], serde_json::json!(0));

        // Chapter 9001 (ch. 12.5) of the cached Suwayomi series 42 ("Fixture 42").
        sqlx::query(
            "INSERT INTO suwayomi_chapter (id, manga_id, name, chapter_number, page_count, updated_at) \
             VALUES (9001, 42, 'Ch 12.5', 12.5, 10, '2026-01-01T00:00:00Z')",
        )
        .execute(&pool)
        .await
        .unwrap();

        // bob comments on series "42" (older) and on chapter 9001 (newer).
        let mut ids = vec![];
        for (tt, tid) in [("series", "42"), ("chapter", "9001")] {
            let m = format!(
                r#"mutation {{ postComment(input: {{ targetType: "{tt}", targetId: "{tid}", body: "on {tt}", hasSpoiler: false }}) {{ id }} }}"#
            );
            let r = exec(&s, &m, Some("bobtok"), "2.2.2.2").await;
            assert!(r.errors.is_empty(), "postComment: {:?}", r.errors);
            ids.push(
                r.data.into_json().unwrap()["postComment"]["id"]
                    .as_str()
                    .unwrap()
                    .to_string(),
            );
        }
        // Pin distinct timestamps so newest-first is deterministic.
        for (id, at) in [
            (&ids[0], "2026-01-01T00:00:00Z"),
            (&ids[1], "2026-01-02T00:00:00Z"),
        ] {
            sqlx::query("UPDATE comments SET created_at = ? WHERE id = ?")
                .bind(at)
                .bind(id)
                .execute(&pool)
                .await
                .unwrap();
        }
        // admin likes + replies to bob's series comment, and comments on their own —
        // which must NOT show up in bob's list.
        let like = format!(
            r#"mutation {{ voteComment(commentId: "{}", value: 1) {{ likes }} }}"#,
            ids[0]
        );
        assert!(exec(&s, &like, Some("admintok"), "1.1.1.1")
            .await
            .errors
            .is_empty());
        let reply = format!(
            r#"mutation {{ postComment(input: {{ targetType: "series", targetId: "42", parentId: "{}", body: "re", hasSpoiler: false }}) {{ id }} }}"#,
            ids[0]
        );
        assert!(exec(&s, &reply, Some("admintok"), "1.1.1.1")
            .await
            .errors
            .is_empty());

        let r = exec(
            &s,
            r#"{ myComments { total hasNextPage items { id targetType targetId body likes dislikes replyCount seriesId seriesTitle chapterNumber } } }"#,
            Some("bobtok"),
            "2.2.2.2",
        )
        .await;
        assert!(r.errors.is_empty(), "myComments: {:?}", r.errors);
        let d = r.data.into_json().unwrap()["myComments"].clone();
        assert_eq!(d["total"], serde_json::json!(2));
        assert_eq!(d["hasNextPage"], serde_json::json!(false));
        let items = d["items"].as_array().unwrap();
        assert_eq!(items.len(), 2);

        // Newest first: the chapter comment, resolved to its owning series + number.
        assert_eq!(items[0]["id"], serde_json::json!(ids[1]));
        assert_eq!(items[0]["targetType"], serde_json::json!("chapter"));
        assert_eq!(items[0]["seriesId"], serde_json::json!("42"));
        assert_eq!(items[0]["seriesTitle"], serde_json::json!("Fixture 42"));
        assert_eq!(items[0]["chapterNumber"], serde_json::json!("12.5"));
        assert_eq!(items[0]["likes"], serde_json::json!(0));
        assert_eq!(items[0]["replyCount"], serde_json::json!(0));

        assert_eq!(items[1]["id"], serde_json::json!(ids[0]));
        assert_eq!(items[1]["targetType"], serde_json::json!("series"));
        assert_eq!(items[1]["seriesId"], serde_json::json!("42"));
        assert_eq!(items[1]["seriesTitle"], serde_json::json!("Fixture 42"));
        assert_eq!(items[1]["chapterNumber"], serde_json::Value::Null);
        assert_eq!(items[1]["likes"], serde_json::json!(1));
        assert_eq!(items[1]["replyCount"], serde_json::json!(1));
    }

