    #[tokio::test]
    async fn work_sources_returns_mappings_ordered_and_extension_joined() {
        let (s, pool) = setup_full(100).await;
        // A MangaDex-native mapping (no extension) plus a Suwayomi mapping whose
        // source_id has catalogued extension coordinates.
        crate::catalog::upsert_work_from_mangadex(
            &pool,
            "md-x",
            &crate::catalog::WorkInput {
                primary_title: Some("Joined Work".into()),
                is_nsfw: false,
                ..Default::default()
            },
        )
        .await
        .unwrap();
        let work_id: String =
            sqlx::query_scalar("SELECT work_id FROM source_series WHERE source_key = 'md-x'")
                .fetch_one(&pool)
                .await
                .unwrap();
        crate::catalog::upsert_source_series(
            &pool, &work_id, "suwayomi", "1024", "slug-1", None, false,
        )
        .await
        .unwrap();
        crate::catalog::upsert_source_extension(
            &pool,
            "1024",
            &crate::catalog::SourceExtensionInput {
                pkg_name: "pkg.x".into(),
                repo_url: "https://r".into(),
                apk_name: None,
                version_code: Some(7),
                lang: Some("en".into()),
                is_nsfw: false,
            },
        )
        .await
        .unwrap();

        let q = format!(
            r#"{{ workSources(workId: "{work_id}") {{ sourceType sourceId sourceKey isNsfw lang extension {{ pkgName repoUrl versionCode }} }} }}"#
        );
        let r = exec(&s, &q, Some("bobtok"), "1.1.1.1").await;
        assert!(r.errors.is_empty(), "unexpected: {:?}", r.errors);
        let data = r.data.into_json().unwrap();
        let rows = data["workSources"].as_array().unwrap();
        assert_eq!(rows.len(), 2, "both source mappings surface");
        // The MangaDex-native mapping sorts first and has no extension.
        assert_eq!(rows[0]["sourceType"], serde_json::json!("mangadex"));
        assert_eq!(rows[0]["extension"], serde_json::Value::Null);
        // The Suwayomi mapping carries its joined extension coordinates.
        assert_eq!(rows[1]["sourceType"], serde_json::json!("suwayomi"));
        assert_eq!(rows[1]["sourceKey"], serde_json::json!("slug-1"));
        assert_eq!(rows[1]["extension"]["pkgName"], serde_json::json!("pkg.x"));
        assert_eq!(
            rows[1]["extension"]["repoUrl"],
            serde_json::json!("https://r")
        );
        assert_eq!(rows[1]["extension"]["versionCode"], serde_json::json!(7));
        assert_eq!(rows[1]["lang"], serde_json::json!("en"));
    }

    /// `Series.workId` is the reader's only bridge from a numeric Suwayomi id to the
    /// work behind it — and therefore to that work's SIBLING sources. Browse links a
    /// Suwayomi-anchored work by its numeric `reader_id`, so without this the series
    /// page rendered a three-source work as single-source (no picker at all).
    ///
    /// Asserts the whole bridge, not just the field: numeric id → work → siblings.
    #[tokio::test]
    async fn mangadex_metadata_resolves_both_ids_and_refresh_preserves_curation() {
        let (s, pool) = setup_full(100).await;
        let mid = "a77742b1-befd-49a4-bff5-1ad4e6b0ef7b";
        let mut input = catalog::WorkInput {
            primary_title: Some("Imported title".into()),
            year: Some(2020),
            original_language: Some("ja".into()),
            demographic: Some("shounen".into()),
            content_rating: Some("safe".into()),
            tags: vec!["Action".into()],
            tag_details: vec![catalog::SourceTag {
                id: Some("391b0423-d847-456f-aff0-8b0cfc03066b".into()),
                name: "Action".into(),
                group: "genre".into(),
            }],
            external_ids: vec![
                ("al".into(), "123".into()),
                ("mu".into(), "abc123x".into()),
                ("ap".into(), "../../evil".into()),
            ],
            official_links: vec![
                ("engtl".into(), "https://publisher.example/title".into()),
                ("raw".into(), "javascript:alert(1)".into()),
            ],
            ..Default::default()
        };
        let work = catalog::upsert_work_from_mangadex(&pool, mid, &input)
            .await
            .unwrap();
        catalog::upsert_source_series(&pool, &work, "suwayomi", "src-a", "42", None, false)
            .await
            .unwrap();
        let fields = "metadata { year originalLanguage demographic contentRating tags { id name group } trackers { provider externalId url } }";
        let q = format!(
            r#"{{ canonicalSeries(workId: "{work}") {{ {fields} }} series(id: "42") {{ {fields} }} }}"#
        );
        let result = exec(&s, &q, Some("bobtok"), "md-metadata").await;
        assert!(result.errors.is_empty(), "{:?}", result.errors);
        let data = result.data.into_json().unwrap();
        assert_eq!(
            data["canonicalSeries"]["metadata"],
            data["series"]["metadata"]
        );
        let metadata = &data["canonicalSeries"]["metadata"];
        assert_eq!(metadata["year"], 2020);
        assert_eq!(metadata["tags"][0]["group"], "genre");
        assert_eq!(metadata["trackers"].as_array().unwrap().len(), 4);
        assert!(metadata["trackers"].as_array().unwrap().iter().any(|t| {
            t["provider"] == "engtl" && t["url"] == "https://publisher.example/title"
        }));
        assert!(metadata["trackers"]
            .as_array()
            .unwrap()
            .iter()
            .all(|t| t["url"].as_str().unwrap().starts_with("https://")));
        sqlx::query("UPDATE work SET title_override = 'Curated title' WHERE id = ?")
            .bind(&work)
            .execute(&pool)
            .await
            .unwrap();
        sqlx::query("INSERT INTO work_tag (work_id, tag, ord, source) VALUES (?, 'My custom tag', 0, 'admin')").bind(&work).execute(&pool).await.unwrap();
        input.external_ids = vec![("al".into(), "456".into())];
        input.official_links.clear();
        input.tags.clear();
        input.tag_details.clear();
        input.year = Some(2021);
        catalog::upsert_work_from_mangadex(&pool, mid, &input)
            .await
            .unwrap();
        let q = format!(r#"{{ canonicalSeries(workId: "{work}") {{ title {fields} }} }}"#);
        let result = exec(&s, &q, Some("bobtok"), "md-metadata").await;
        assert!(result.errors.is_empty(), "{:?}", result.errors);
        let series = result.data.into_json().unwrap()["canonicalSeries"].clone();
        assert_eq!(series["title"], "Curated title");
        assert_eq!(series["metadata"]["year"], 2021);
        assert_eq!(series["metadata"]["tags"][0]["group"], "custom");
        assert_eq!(series["metadata"]["tags"][0]["name"], "My custom tag");
        let trackers = series["metadata"]["trackers"].as_array().unwrap();
        assert_eq!(
            trackers.len(),
            2,
            "removed upstream links leave the current snapshot"
        );
        assert!(trackers
            .iter()
            .any(|t| t["provider"] == "al" && t["externalId"] == "456"));
        let historical: i64 = sqlx::query_scalar(
            "SELECT COUNT(*) FROM work_external_id WHERE work_id = ? AND provider = 'al'",
        )
        .bind(&work)
        .fetch_one(&pool)
        .await
        .unwrap();
        assert_eq!(
            historical, 2,
            "display refresh must preserve historical identity keys"
        );
        sqlx::query("UPDATE work SET metadata_synced_at = 'done', covers_synced_at = 'done', mangadex_details_synced_at = NULL WHERE id = ?").bind(&work).execute(&pool).await.unwrap();
        assert!(works_needing_enrichment(&pool, 100)
            .await
            .unwrap()
            .contains(&mid.to_string()));
        catalog::refresh_mangadex_details(&pool, &work, &input)
            .await
            .unwrap();
        assert!(!works_needing_enrichment(&pool, 100)
            .await
            .unwrap()
            .contains(&mid.to_string()));
    }

    #[tokio::test]
    async fn series_work_id_bridges_a_numeric_id_to_its_sibling_sources() {
        let (s, pool) = setup_full(100).await;
        // Cached, so `series(id:)` resolves without a Suwayomi round trip.
        sqlx::query(
            "INSERT INTO suwayomi_series (id, title, status, source_id, chapter_count, updated_at) \
             VALUES (777, 'Multi Source', 'ONGOING', 'src-a', 0, '2020-01-01T00:00:00Z')",
        )
        .execute(&pool)
        .await
        .unwrap();
        crate::catalog::upsert_work_from_mangadex(
            &pool,
            "md-multi",
            &crate::catalog::WorkInput {
                primary_title: Some("Multi Source".into()),
                is_nsfw: false,
                ..Default::default()
            },
        )
        .await
        .unwrap();
        let work_id: String =
            sqlx::query_scalar("SELECT work_id FROM source_series WHERE source_key = 'md-multi'")
                .fetch_one(&pool)
                .await
                .unwrap();
        // Two Suwayomi mirrors of the one work; `777` is the id the reader arrives with.
        for (source_id, source_key) in [("src-a", "777"), ("src-b", "888")] {
            crate::catalog::upsert_source_series(
                &pool, &work_id, "suwayomi", source_id, source_key, None, false,
            )
            .await
            .unwrap();
        }

        let r = exec(
            &s,
            r#"{ series(id: "777") { id workId } }"#,
            Some("bobtok"),
            "1.1.1.1",
        )
        .await;
        assert!(r.errors.is_empty(), "unexpected: {:?}", r.errors);
        let resolved = r.data.into_json().unwrap()["series"]["workId"].clone();
        assert_eq!(
            resolved,
            serde_json::json!(work_id),
            "a numeric id must report the work it belongs to"
        );

        // The point of the bridge: that work carries the sources the picker needs.
        let q = format!(r#"{{ workSources(workId: "{work_id}") {{ sourceKey }} }}"#);
        let r = exec(&s, &q, Some("bobtok"), "1.1.1.1").await;
        assert!(r.errors.is_empty(), "unexpected: {:?}", r.errors);
        let mut keys: Vec<String> = r.data.into_json().unwrap()["workSources"]
            .as_array()
            .unwrap()
            .iter()
            .map(|row| row["sourceKey"].as_str().unwrap().to_string())
            .collect();
        keys.sort();
        assert_eq!(
            keys,
            vec!["777", "888", "md-multi"],
            "the work behind `777` exposes every sibling source, not just the one asked for"
        );
    }

