    #[tokio::test]
    async fn simultaneous_guesses_cannot_bypass_login_budget() {
        let s = setup_with_limit(2).await;
        let wrong = r#"mutation { login(username:"bob", password:"wrong") { token } }"#;
        let (a, b, c) = tokio::join!(
            exec(&s, wrong, None, "concurrent-login"),
            exec(&s, wrong, None, "concurrent-login"),
            exec(&s, wrong, None, "concurrent-login")
        );
        let errors = [first_error(&a), first_error(&b), first_error(&c)];
        assert_eq!(
            errors
                .iter()
                .filter(|e| e.as_str() == "Invalid username or password")
                .count(),
            2
        );
        assert_eq!(
            errors
                .iter()
                .filter(|e| e.contains("Too many login attempts"))
                .count(),
            1
        );
    }

    #[tokio::test]
    async fn password_jobs_reject_when_all_memory_slots_are_busy() {
        let (s, _, app) = setup_with_state(100).await;
        let permits = app
            .password_work
            .clone()
            .acquire_many_owned(4)
            .await
            .unwrap();
        let right = r#"mutation { login(username:"bob", password:"password123") { token } }"#;
        let blocked = exec(&s, right, None, "password-busy").await;
        assert!(first_error(&blocked).contains("Sign-in is busy"));
        drop(permits);
        assert!(exec(&s, right, None, "password-ready")
            .await
            .errors
            .is_empty());
    }

    /// Guesses at ONE account from many addresses stop at the account's own budget
    /// (3 times one address's), however the name is spelled. Other accounts go on.
    #[tokio::test]
    async fn rate_limit_also_keys_on_the_account() {
        let s = setup_with_limit(1).await;
        let guess = |name: &str| {
            format!(r#"mutation {{ login(username:"{name}", password:"nope") {{ token }} }}"#)
        };
        for (ip, name) in [("9.9.9.1", "bob"), ("9.9.9.2", "BOB"), ("9.9.9.3", "Bob")] {
            let r = exec(&s, &guess(name), None, ip).await;
            assert_eq!(first_error(&r), "Invalid username or password");
        }
        // A new address, and even the right password: the account is closed for now.
        let right = r#"mutation { login(username:"bob", password:"password123") { token } }"#;
        let blocked = exec(&s, right, None, "9.9.9.4").await;
        assert!(
            first_error(&blocked).contains("Too many login attempts"),
            "got: {}",
            first_error(&blocked)
        );
        let other = exec(&s, &guess("admin"), None, "9.9.9.5").await;
        assert_eq!(first_error(&other), "Invalid username or password");
        // A name no account can have is refused before it becomes a limiter key.
        let long = exec(&s, &guess(&"x".repeat(200)), None, "9.9.9.6").await;
        assert_eq!(first_error(&long), "Invalid username or password");
    }

    #[tokio::test]
    async fn rate_limit_keys_on_ip_and_counts_successes() {
        let s = setup_with_limit(2).await;
        let wrong = r#"mutation { login(username:"bob", password:"nope") { token } }"#;
        let right = r#"mutation { login(username:"bob", password:"password123") { token } }"#;
        // two failures from the attacker IP exhaust its budget
        for _ in 0..2 {
            let r = exec(&s, wrong, None, "9.9.9.9").await;
            assert_eq!(first_error(&r), "Invalid username or password");
        }
        // third attempt from that IP is blocked...
        let blocked = exec(&s, right, None, "9.9.9.9").await;
        assert!(
            first_error(&blocked).contains("Too many login attempts"),
            "got: {}",
            first_error(&blocked)
        );
        // ...but the victim's own IP is unaffected (M1)
        let victim = exec(&s, right, None, "8.8.8.8").await;
        assert!(
            victim.errors.is_empty(),
            "cross-IP lockout: {:?}",
            victim.errors
        );
        // Valid credentials cannot bypass the expensive-verification budget.
        for _ in 0..2 {
            let r = exec(&s, right, None, "7.7.7.7").await;
            assert!(r.errors.is_empty(), "{:?}", r.errors);
        }
        let blocked = exec(&s, right, None, "7.7.7.7").await;
        assert!(first_error(&blocked).contains("Too many login attempts"));
    }

