    #[tokio::test]
    async fn set_user_admin_demotion_purges_sessions() {
        let (s, pool) = setup_full(100).await;
        // Demote bob (already flagged non-admin — the UPDATE still matches the
        // row, so the purge branch must run the same way it does for a real
        // demotion).
        let r = exec(
            &s,
            r#"mutation { setUserAdmin(userId:"bob-id", isAdmin:false) { isAdmin } }"#,
            Some("admintok"),
            "1.1.1.1",
        )
        .await;
        assert!(r.errors.is_empty(), "demote failed: {:?}", r.errors);
        let n: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM sessions WHERE user_id = 'bob-id'")
            .fetch_one(&pool)
            .await
            .unwrap();
        assert_eq!(n, 0, "demotion purged bob's sessions");
        // admin's own sessions are untouched.
        let admin_n: i64 =
            sqlx::query_scalar("SELECT COUNT(*) FROM sessions WHERE user_id = 'admin-id'")
                .fetch_one(&pool)
                .await
                .unwrap();
        assert_eq!(admin_n, 1);
    }

    #[tokio::test]
    async fn revoke_all_sessions_spares_the_current_device() {
        let (s, pool) = setup_full(100).await;
        // An anonymous caller is rejected like any signed-in mutation.
        let q = r#"mutation { revokeAllSessions }"#;
        assert_eq!(
            first_error(&exec(&s, q, None, "1.1.1.1").await),
            "Not authenticated"
        );

        // Bob holds a SECOND live session besides the presented "bobtok".
        sqlx::query(
            "INSERT INTO sessions (token, user_id, created_at, expires_at) \
             VALUES (?, 'bob-id', '2020-01-01T00:00:00Z', '2999-01-01T00:00:00Z')",
        )
        .bind(auth::hash_token("bobtok2"))
        .execute(&pool)
        .await
        .unwrap();

        let r = exec(&s, q, Some("bobtok"), "1.1.1.1").await;
        assert!(
            r.errors.is_empty(),
            "revokeAllSessions failed: {:?}",
            r.errors
        );
        assert_eq!(
            r.data.into_json().unwrap()["revokeAllSessions"],
            serde_json::json!(true)
        );

        // The presented token's row survives (current device stays logged in);
        // every other session of bob's is gone.
        let tok = auth::user_for_token(&pool, "bobtok").await.unwrap();
        assert!(tok.is_some(), "the current session must stay valid");
        let n: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM sessions WHERE user_id = 'bob-id'")
            .fetch_one(&pool)
            .await
            .unwrap();
        assert_eq!(n, 1, "other sessions purged");
    }

    /// `total` must count EXACTLY the rows the pages return — the property this test was
    /// written for, and the one it still asserts.
    ///
    /// WHAT CHANGED (2026-07-31, F3-gate removal): it used to also pin the gate, asserting
    /// that the row with a NULL `last_new_chapter_at` was excluded. That predicate is gone
    /// from this resolver — see `updates_admits_a_series_our_scanner_never_saw_change` for
    /// why and for the membership rules that remain — so all three enrolled, in-library rows
    /// are now counted and all three are returned. The count/page equality below is
    /// unchanged and is what this test is really for: `total` once counted every dated
    /// `series_scan_state` row regardless of `in_library`, which inflated the pager past what
    /// the pages could return.
    #[tokio::test]
    async fn updates_total_counts_exactly_the_rows_the_page_returns() {
        // Build state directly so we can seed series_scan_state, then query updates.
        let pool = TestPoolOptions::new()
            .max_connections(1)
            .connect("sqlite::memory:")
            .await
            .unwrap();
        sqlx::migrate!("./migrations")
            .run(pool.write())
            .await
            .unwrap();
        for (sid, ts) in [
            ("10", Some("2026-02-01T00:00:00Z")),
            ("11", Some("2026-03-01T00:00:00Z")),
            ("12", None),
        ] {
            // Every scan-state row needs its library `suwayomi_series` counterpart: the
            // feed reads the release-time sort key from there, so `in_library = 1` is
            // now part of what `total` counts.
            sqlx::query(
                "INSERT INTO suwayomi_series \
                   (id, title, status, source_id, chapter_count, in_library, latest_chapter_at, updated_at) \
                 VALUES (?, ?, 'ONGOING', 'src', 0, 1, '1751328000000', '2026-01-01T00:00:00Z')",
            )
            .bind(sid)
            .bind(format!("Series {sid}"))
            .execute(&pool)
            .await
            .unwrap();
            sqlx::query(
                "INSERT INTO series_scan_state \
                   (series_id, avg_interval_hours, known_chapter_count, last_new_chapter_at, updated_at) \
                 VALUES (?, 0, 0, ?, '2026-01-01T00:00:00Z')",
            )
            .bind(sid)
            .bind(ts)
            .execute(&pool)
            .await
            .unwrap();
        }
        let state = std::sync::Arc::new(AppState {
            pool: pool.clone(),
            cover_pool: pool.clone(),
            suwayomi: crate::suwayomi::SuwayomiClient::new("http://127.0.0.1:1".into(), None, None),
            mangadex: std::sync::Arc::new(crate::mangadex::MangaDexClient::new(
                "test-ua", 5.0, 40.0,
            )),
            admin_users: vec![],
            scan_health: Mutex::new(ScanHealth::default()),
            auth_limiter: RateLimiter::new(100, 60),
            comment_limiter: comment_limiter(),
            password_work: std::sync::Arc::new(tokio::sync::Semaphore::new(4)),
            federated_limiter: RateLimiter::new(100, 60),
            session_ttl_secs: 30 * 24 * 60 * 60,
            series_inflight: KeyedLocks::default(),
            chapters_inflight: KeyedLocks::default(),
            cover_crawl_running: std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false)),
            catalogue_cover_phash: false,
            ext_icons_dir: std::path::PathBuf::new(),
            setup_code: crate::instance::SetupCode::default(),
        });
        let s = build_schema(state, false);
        let r = exec(
            &s,
            r#"{ updates { total hasNextPage items { id } } }"#,
            None,
            "1.1.1.1",
        )
        .await;
        assert!(r.errors.is_empty(), "updates errored: {:?}", r.errors);
        let data = r.data.into_json().unwrap();
        // All three are enrolled and in library. The one with a NULL `last_new_chapter_at`
        // is admitted now: it is a series we have watched but never caught mid-update, not a
        // series with nothing to show.
        assert_eq!(data["updates"]["total"], serde_json::json!(3));
        assert_eq!(data["updates"]["hasNextPage"], serde_json::json!(false));
        // Suwayomi is unreachable here, but hydration is DB-first, so the three
        // `suwayomi_series` rows resolve from cache. They share one `latest_chapter_at`,
        // so the `id DESC` tiebreaker decides the order.
        let ids: Vec<&str> = data["updates"]["items"]
            .as_array()
            .unwrap()
            .iter()
            .map(|i| i["id"].as_str().unwrap())
            .collect();
        assert_eq!(
            ids,
            vec!["12", "11", "10"],
            "items must be exactly the counted rows, tie broken by id DESC"
        );
        assert_eq!(
            ids.len() as i64,
            data["updates"]["total"].as_i64().unwrap(),
            "total must equal what the single page returns"
        );
    }

